define(['jquery','Magento_Customer/js/customer-data'],function($,customerData){'use strict';return function(config){if(!config||!config.hasCoupon){return;}
function updateCouponCode(){var cart=customerData.get('cart')(),el=document.getElementById('applied-coupon-code'),code;if(!el||!cart||!cart.totalsData){return;}
code=(cart.totalsData.extension_attributes&&cart.totalsData.extension_attributes.coupon_label)||cart.totalsData.coupon_code||'';if(el.textContent!==code){el.textContent=code;}}
updateCouponCode();customerData.get('cart').subscribe(updateCouponCode);};});